// Utility Studio Workspace: Collections and follow-up worklists. Disconnection notices, winter moratorium holds, rejected
// payments and overdue accounts (POST /api/m2c/collections), an account's collections record (/m2c/collections/account),
// the outage follow-up list (/m2c/outage-followup) and AMI collector groups (/m2c/collector-groups). Rows, amounts,
// states and the actions offered all come from the engine: a button is shown only when the row's `actions` has it, and
// each one is an append-only engine action on the run date (09:00). workspace.js mounts these pages and their nav.
import {escapeText as e} from './customer-view.js';

export const COLLECTION_LISTS=[['disconnect','Disconnection notices'],['moratorium','Winter moratorium holds'],['rejected','Rejected payments'],['overdue','Overdue accounts']];
export const COLLECTION_TRANSACTIONS=[['Collections','collections','Collections Worklists'],['Collections','outages','Outage Follow-up']];
export const PERIODS=[['ytd','Year to date'],['month','This month'],['30d','Last 30 days'],['run','Since the run started']];
export const ACTION_LABELS={disconnect_approve:'Approve disconnection',disconnect_cancel:'Cancel disconnection',payment_arrangement:'Payment arrangement',extend_due:'Extend due date',dunning_hold:'Hold dunning',low_income_referral:'Refer to low income',budget_billing:'Enrol in budget billing','waive_fee:late_fee':'Waive late fee','waive_fee:nsf_fee':'Waive NSF fee'};
const ACCOUNT_ACTIONS=['payment_arrangement','dunning_hold','low_income_referral','budget_billing'];
const PRIMARY={disconnect:['disconnect_approve','disconnect_cancel'],moratorium:['payment_arrangement','low_income_referral'],rejected:['waive_fee:nsf_fee','payment_arrangement'],overdue:['payment_arrangement','dunning_hold']}; // the rest go in "More…"
const STATES={pending:'Awaiting decision',approved:'Approved',disconnected:'Disconnected',reconnected:'Reconnected',cancelled:'Cancelled',paid:'Paid',arranged:'Under arrangement',held:'Held for the winter','notice issued':'Notice issued',repaid:'Repaid',unpaid:'Unpaid'};
const SORTS=[['age','Oldest first'],['amount','Largest amount'],['created','Newest first']];
const KINDS=[['','All rows'],['last_gasp','AMI last gasps'],['lost_use','Use lost'],['missed_read','Missed reads']];
const PAGE=50;

// Routes: #/workspace/collections/<list>, #/workspace/account/<id>, #/workspace/outages, #/workspace/collector/<id>/<day>.
export function parseCollectionsRoute(parts){const [head,a=null,b=null]=parts;
 if(head==='collections')return {tx:'collections',list:COLLECTION_LISTS.some(l=>l[0]===a)?a:'disconnect'};
 if(head==='account'&&a)return {tx:'account',record:a};
 if(head==='outages')return {tx:'outages'};
 if(head==='collector'&&a)return {tx:'collector',record:a,...(b?{day:b}:{})};
 return null;}
export function collectionsHash(r){
 if(r.tx==='collections')return '#/workspace/collections/'+(r.list||'disconnect');
 if(r.tx==='account')return '#/workspace/account/'+encodeURIComponent(r.record);
 if(r.tx==='outages')return '#/workspace/outages';
 if(r.tx==='collector')return `#/workspace/collector/${encodeURIComponent(r.record)}${r.day?'/'+r.day:''}`;
 return null;}
export const isCollectionsRoute=r=>['collections','account','outages','collector'].includes(r?.tx);
// Run statistics: the day a period starts (null: year to date, the summary as it is). "Since the run started" is your
// first action's day; with no actions yet it is the year.
export function periodStart(period,asOf,firstAction){if(!asOf||period==='ytd')return null;if(period==='month')return asOf.slice(0,8)+'01';
 if(period==='30d'){const d=new Date(Date.parse(asOf+'T12:00:00Z')-29*86400000).toISOString().slice(0,10);return d<'2026-01-01'?'2026-01-01':d;}
 if(period==='run')return firstAction&&firstAction<=asOf?firstAction:null;return null;}
// The engine action behind a button: its type and fields (`input` is what the dialog asked for).
export function actionBody(act,target,input={}){const [type,fee]=String(act).split(':'),body={type};
 if(ACCOUNT_ACTIONS.includes(type))body.accountId=target.accountId;else body.invoiceId=target.invoiceId;
 if(fee)body.fee=fee;if(type==='payment_arrangement')body.instalments=Number(input.instalments||3);if(type==='extend_due'||type==='dunning_hold')body.days=Number(input.days||(type==='extend_due'?14:30));
 const note=String(input.note??'').trim();if(note)body.note=note;return body;}
// What the dialog asks before an action: a number (instalments, days) and a note (required for a hold or a cancellation).
export function actionForm(act,target={}){const [type]=String(act).split(':'),who=target.invoiceId||target.accountId||'',note=(required,label='Note')=>({name:'note',label,kind:'textarea',required});
 const f={payment_arrangement:{text:`Account ${target.accountId}: what is overdue today becomes monthly instalments, the first due in a week. Dunning on those bills stops while the customer pays.`,fields:[{name:'instalments',label:'Instalments (2–12)',kind:'number',min:2,max:12,value:3,required:true},note(false)]},
  extend_due:{text:`${who}: dunning restarts from the new due date.`,fields:[{name:'days',label:'Days to add (1–60)',kind:'number',min:1,max:60,value:14,required:true},note(false)]},
  dunning_hold:{text:`Account ${target.accountId}: no reminders, notices or disconnection until the hold ends.`,fields:[{name:'days',label:'Hold for days (1–90)',kind:'number',min:1,max:90,value:30,required:true},note(true,'Reason')]},
  disconnect_cancel:{text:`${who}: no disconnection for this notice.`,fields:[note(true,'Reason')]},
  disconnect_approve:{text:`${who}: a crew disconnects at 10:00 on the earliest disconnection date (or the next morning) if the bill is still unpaid.`,fields:[note(false)]},
  low_income_referral:{text:`Account ${target.accountId}: the low-income agency decides in about ten business days; dunning waits meanwhile.`,fields:[note(false)]},
  budget_billing:{text:`Account ${target.accountId}: a collections agent sets up the plan; later bills are levelled to its monthly instalment.`,fields:[note(false)]}}[type]||{text:`${who}`,fields:[note(false)]};
 return {title:ACTION_LABELS[act]||act,submit:ACTION_LABELS[act]||'Record',...f};}

const money=n=>n==null?'—':new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(n);
const num=(v,d=1)=>v==null?'—':new Intl.NumberFormat('en-CA',{maximumFractionDigits:d}).format(v);
const LOCAL_DAY=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}),LOCAL_HM=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Toronto',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
const day=iso=>!iso?'—':String(iso).length>10?LOCAL_DAY.format(new Date(iso)):String(iso).slice(0,10);
const hm=iso=>iso&&String(iso).length>10?LOCAL_HM.format(new Date(iso)):'';
const field=(label,value)=>`<div class="gui-field"><span>${e(label)}</span><span class="gui-value" title="${value==null?'':e(String(value))}">${value==null||value===''?'—':e(String(value))}</span></div>`;
const group=(title,body,extra='')=>`<fieldset class="gui-group ${extra}"><legend>${e(title)}</legend>${body}</fieldset>`;
const table=(heads,rows,none)=>`<div class="ws-table-wrap"><table class="gui-history-table ws-col-small"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x==null||x===''?'—':x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">${none}</td></tr>`}</tbody></table></div>`;
const acctLink=(id,text=id)=>id?`<button type="button" class="fiori-link" data-col-go="account" data-id="${e(id)}">${e(text)}</button>`:'—';
const caseLink=id=>id?`<button type="button" class="fiori-link" data-col-go="case" data-id="${e(id)}">${e(id)}</button>`:'—';
const flagText=f=>!f?'':[f.arrangementId?'arrangement':'',f.dunningHoldUntil?'dunning held to '+f.dunningHoldUntil:'',f.lowIncome?'low income '+f.lowIncome:'',f.budgetBilling?'budget billing'+(f.budgetBilling==='pending'?' (pending)':''):'',f.disconnected?'disconnected':''].filter(Boolean).join(' · ');
const keyOf=(act,t)=>'col:'+act+':'+(t.invoiceId||t.accountId||'');
const isAccountAction=act=>ACCOUNT_ACTIONS.includes(String(act).split(':')[0]);
const invoiceActs=i=>(i.actions||[]).filter(a=>!isAccountAction(a)); // the account's own actions sit above the invoices
// An action button (or the "More…" menu) for a row; `acting` is the action the engine is recording now.
function actButton(act,t,acting){const k=keyOf(act,t);return `<button type="button" class="ws-col-act" data-col-act="${e(act)}" data-account="${e(t.accountId||'')}" data-invoice="${e(t.invoiceId||'')}"${acting?' disabled':''}>${acting?.act===k?'Recording…':e(ACTION_LABELS[act]||act)}</button>`;}
export function rowActions(list,row,acting=null){const acts=row.actions||[];if(!acts.length)return '<span class="ws-col-none">No action today</span>';const lead=(PRIMARY[list]||[]).filter(a=>acts.includes(a)),rest=acts.filter(a=>!lead.includes(a));
 return `<div class="ws-col-acts">${lead.map(a=>actButton(a,row,acting)).join('')}${rest.length?`<select class="ws-col-more" data-col-more data-account="${e(row.accountId||'')}" data-invoice="${e(row.invoiceId||'')}" aria-label="More actions for ${e(row.invoiceId||row.accountId)}"${acting?' disabled':''}><option value="">More…</option>${rest.map(a=>`<option value="${e(a)}">${e(ACTION_LABELS[a]||a)}</option>`).join('')}</select>`:''}</div>`;}
// One list's table: header and rows (the engine's fields, as of the run date).
export function listTable(list,rows,acting=null){const H={disconnect:['Notice','Invoice','Account','Address','Outstanding','Overdue','State','Actions'],moratorium:['Held on','Invoice','Account','Address','Utilities','Outstanding','Held until','State','Actions'],rejected:['Rejected','Invoice','Account','Address','Amount','NSF fee','Repaid','State','Actions'],overdue:['Account','Customer','Address','Overdue','Bills','Oldest due','Age','Last dunning','Collections work','Actions']}[list];
 const state=r=>`${e(STATES[r.state]||r.state||'')}${r.state==='pending'?`<br><small>from ${e(r.earliestDisconnectAt)}</small>`:r.state==='approved'?`<br><small>crew ${e(day(r.scheduledAt))}</small>`:r.state==='disconnected'?`<br><small>${e(day(r.disconnectedAt))}</small>`:''}${r.heldBy?`<br><small class="ws-col-held">${e(r.heldBy)}</small>`:''}`;
 const who=r=>`${acctLink(r.accountId)}${r.name?`<br><small>${e(r.name)}</small>`:''}`;
 const cells=r=>({disconnect:[day(r.noticeAt),e(r.invoiceId),who(r),e(r.address||''),money(r.outstanding),r.daysOverdue?r.daysOverdue+' d':'—',state(r),rowActions(list,r,acting)],
  moratorium:[day(r.heldAt),e(r.invoiceId),who(r),e(r.address||''),e((r.commodities||[]).join(', ')),money(r.outstanding),e(r.heldUntil),state(r),rowActions(list,r,acting)],
  rejected:[day(r.rejectedAt),e(r.invoiceId),who(r),e(r.address||''),money(r.amount),r.nsfFee?money(r.nsfFee)+(r.nsfWaived?' (waived)':''):'—',day(r.repaidAt),state(r),rowActions(list,r,acting)],
  overdue:[acctLink(r.accountId),e(r.name||''),e(r.address||''),money(r.overdue),r.invoices,e(r.oldestDueAt),r.ageDays+' d',r.lastDunning?`${e(r.lastDunning.label)}<br><small>${e(day(r.lastDunning.at))}</small>`:'—',e(flagText(r.flags)),rowActions(list,r,acting)]}[list]);
 return `<table class="clarification-table ws-col-table"><thead><tr>${H.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr class="${r.open===false?'ws-col-closed':''}">${cells(r).map(x=>`<td>${x==null||x===''?'—':x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${H.length}" class="fiori-empty">Nothing in this list for the selected filters.</td></tr>`}</tbody></table>`;}
// The AMI collector behind a missed read and the other cases on it that day (case page), and a collections case's account.
export function caseExtras(c){const n=c?.network,k=c?.collections;let out='';
 if(n)out+=group('AMI Network',`<div class="gui-master-grid"><div>${field('Collector',n.collectorId)}${field('Mounted on',[n.mountedOn,n.mountId].filter(Boolean).join(' · ').replaceAll('_',' '))}</div><div>${field('Missed reads that day',n.cases)}${n.cases>1?`<div class="gui-inline-actions"><button type="button" class="gui-yellow" data-col-go="collector" data-id="${e(n.collectorId)}" data-day="${e(n.day)}">${n.cases} cases on collector ${e(n.collectorId)} ›</button></div>`:''}</div></div>${(n.relatedCases||[]).length?table(['Related case','Address','Status'],n.relatedCases.slice(0,8).map(x=>[caseLink(x.caseId),e(x.address),e(x.status+(x.outcome?' · '+x.outcome:''))]),'')+(n.relatedCases.length>8?`<p class="small-note">${n.relatedCases.length-8} more on the collector page.</p>`:''):''}`);
 if(k)out+=group('Account Collections',`<div class="gui-master-grid"><div>${field('Contract Acct',k.accountId)}${field('Overdue',money(k.overdue))}${field('Outstanding',money(k.outstanding))}</div><div>${k.referral?field('Agency decision',k.referral.outcome?`${k.referral.outcome}${k.referral.grant?' · grant '+money(k.referral.grant):''}`:'by '+k.referral.decideBy):''}${k.plan?field('Budget plan',`${money(k.plan.instalment)} a month · ${k.plan.active?'since':'from'} ${k.plan.startsAt}`):''}${field('Collections work',flagText(k.flags)||'None')}</div></div><div class="gui-inline-actions"><button type="button" class="gui-yellow" data-col-go="account" data-id="${e(k.accountId)}">Account collections ›</button></div>`);
 return out;}
// Run statistics for a period (the engine's `window`): what happened between the period's start and the run date.
export function periodBody(sum){const w=sum.window,k=w.kpis,b=w.billing,c=w.collections,grid=cols=>`<div class="gui-master-grid ws-stats">${cols.map(col=>`<div>${col.map(([l,v])=>field(l,v)).join('')}</div>`).join('')}</div>`,n=v=>num(v,0),d=b.dunning||{};
 return group(`Period · ${w.since} to ${w.asOf} (${w.days} day${w.days===1?'':'s'})`,`<p class="small-note">Counted inside the period; open cases, overdue and receivable are as at its start and end.</p>`)
  +group('Meter Reading',grid([[['Reads',n(k.reads)],['Actual',n(k.actual)],['Missing',n(k.missing)]],[['Auto-accepted',n(k.autoAccepted)],['Flagged by VEE',n(k.flagged)],['Estimated',n(k.estimated)]]]))
  +group('Work Queues',grid([[['Cases opened',n(k.casesOpened)],['Resolved',n(k.casesResolved)],['Open at start → now',`${n(k.casesOpenAtStart)} → ${n(k.casesOpen)}`]],[['Field orders',n(k.fieldOrders)],['Truck rolls',n(k.truckRolls)],['Days to release',k.avgDaysToRelease??'—']]]))
  +group('Costs',grid([[['Labour',money(k.costs.labor)],['System',money(k.costs.system)],['Customer experience',money(k.costs.cx)]],[['Meter reading',money(k.costs.reads)],['Total',money(k.costs.total)],['Carrying cost',money(k.carry)]]]))
  +group('Billing and Collections',grid([[['Billing documents',n(b.documents)],['Billed',money(b.billed)],['Invoices',n(b.invoices)],['Collected',money(b.collected)]],[['Overdue',`${money(b.overdueAtStart)} → ${money(b.overdue)}`],['Receivable',`${money(b.receivableAtStart)} → ${money(b.receivable)}`],['Reminders · notices',`${n(d.DUNNING_REMINDER||0)} · ${n(d.DUNNING_NOTICE||0)}`],['Disconnect notices',`${n(d.DISCONNECT_NOTICE||0)} (${n(d.MORATORIUM_HOLD||0)} winter holds)`]]]))
  +group('Collections Work',grid([[['Rejected payments',n(d.PAYMENT_REJECTED||0)],['Arrangements',n(c.arrangements)],['Dunning holds',n(c.dunningHolds)],['Disconnections',n(c.disconnections)]],[['Low-income referrals',n(c.lowIncomeReferrals)],['Low-income grants',money(c.lowIncomeGrants)],['Budget enrolments',n(c.budgetEnrolments)],['Fees waived',money(c.feesWaived)]]]));}
// Year to date: the dunning steps and collections work behind the Billing and Collections figures.
export function collectionsGroup(billing){const d=billing?.dunning||{},c=billing?.collections;if(!c)return '';const n=v=>num(v,0),grid=cols=>`<div class="gui-master-grid ws-stats">${cols.map(col=>`<div>${col.map(([l,v])=>field(l,v)).join('')}</div>`).join('')}</div>`;
 return group('Collections',grid([[['Reminders · notices',`${n(d.DUNNING_REMINDER||0)} · ${n(d.DUNNING_NOTICE||0)}`],['Disconnect notices',n(d.DISCONNECT_NOTICE||0)],['Winter holds',n(d.MORATORIUM_HOLD||0)],['Rejected payments',n(d.PAYMENT_REJECTED||0)]],[['Arrangements',`${n(c.arrangements.made)} (${n(c.arrangements.active)} active, ${n(c.arrangements.broken)} broken)`],['Disconnections',`${n(c.disconnections.disconnected+c.disconnections.reconnected)} (${n(c.disconnections.pending)} notices awaiting a decision)`],['Low-income referrals',`${n(c.lowIncome.referred)} · ${money(c.lowIncome.grants)} in grants`],['Budget billing',`${n(c.budgetPlans.enrolled)} enrolled this year · ${n(c.budgetPlans.masterData)} on a plan from master data`]]])+`<div class="gui-inline-actions"><button type="button" class="gui-yellow" data-col-go="collections" data-id="disconnect">Collections worklists ›</button></div>`);}

export function installCollections({getClient,ui,toast,header,statusbar,empty,go,render,recording,refusal,onShowPremise=()=>{},onWatch=()=>{},reopen=()=>{},root}){
 const client=()=>getClient();
 const st={list:'disconnect',status:'open',sort:'age',search:'',commodity:'',page:1,res:null,busy:0,account:null,accountMsg:'',outages:null,of:{utility:'',kind:'',status:'all',search:'',page:1},group:null,rows:null,groupsKey:null,groups:null,period:'ytd'};
 const acting=()=>ui.acting||null;
 // ---- lists ------------------------------------------------------------------------------------------------------
 function nav(active=null){const c=st.res?.counts||{};return `<div>Collections</div><nav aria-label="Collections worklists">${COLLECTION_LISTS.map(([id,l])=>`<button type="button" data-col-go="collections" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${l}${c[id]?`<span class="ws-count">${c[id]}</span>`:''}</button>`).join('')}</nav><div>Meter Reading</div><nav aria-label="Follow-up worklists"><button type="button" data-col-go="outages" class="${active==='outages'?'active':''}" ${active==='outages'?'aria-current="page"':''}>Outage follow-up${st.outages?.total?`<span class="ws-count">${st.outages.total}</span>`:''}</button></nav>`;}
 function pager(res){if(!res||res.total<=res.pageSize)return '';const pages=Math.ceil(res.total/res.pageSize);return `<div class="ws-more ws-col-pager"><button type="button" data-col-page="${res.page-1}" ${res.page<=1?'disabled':''}>‹ Previous</button><span>Page ${res.page} of ${pages}</span><button type="button" data-col-page="${res.page+1}" ${res.page>=pages?'disabled':''}>Next ›</button></div>`;}
 function listPage(){const res=st.res,label=COLLECTION_LISTS.find(l=>l[0]===st.list)[1],picker=`<label class="ws-category-pick"><span>Collections</span><select data-col-list aria-label="Collections worklist">${COLLECTION_LISTS.map(([id,l])=>`<option value="${id}" ${st.list===id?'selected':''}>${l}${res?.counts?.[id]?` (${res.counts[id]})`:''}</option>`).join('')}<option value="outages">Outage follow-up</option></select></label>`;
  const tools=`${st.list==='overdue'?'':`<label class="sr-only" for="ws-col-status">Status</label><select id="ws-col-status" data-col-filter="status">${[['open','Open'],['closed','Closed'],['all','All']].map(([v,l])=>`<option value="${v}" ${st.status===v?'selected':''}>${l}</option>`).join('')}</select>`}<label class="sr-only" for="ws-col-sort">Sort</label><select id="ws-col-sort" data-col-filter="sort">${SORTS.map(([v,l])=>`<option value="${v}" ${st.sort===v?'selected':''}>${l}</option>`).join('')}</select>${st.list==='overdue'?'':`<label class="sr-only" for="ws-col-commodity">Utility</label><select id="ws-col-commodity" data-col-filter="commodity">${[['','All utilities'],['electric','Electric'],['water','Water'],['gas','Gas']].map(([v,l])=>`<option value="${v}" ${st.commodity===v?'selected':''}>${l}</option>`).join('')}</select>`}<input type="search" id="ws-col-search" data-col-search placeholder="Account, invoice, name, address…" value="${e(st.search)}" aria-label="Find in ${e(label)}">${st.search||st.commodity||st.status!=='open'?`<button type="button" class="native-tool" data-col-clear>Clear filters</button>`:''}<span class="spacer"></span><span>${res?`${res.total} ${res.total===1?'item':'items'} · ${money(res.amount)}`:''}</span>`;
  return `<section class="fiori-shell clarification-shell">${header('collections')}<div class="clarification-main-toolbar"><button type="button" data-col-refresh>Update list</button><button type="button" data-col-export>Export list</button><button type="button" data-ws="statistics">Run statistics</button></div><div class="clarification-layout"><aside class="clarification-sidebar">${nav(st.list)}</aside><section class="clarification-main">${picker}<div class="clarification-title">${e(label)}</div><div class="clarification-table-toolbar">${tools}</div><div class="clarification-table-scroll">${res?listTable(st.list,res.rows||[],acting()):'<p class="fiori-empty">Loading the worklist from the engine…</p>'}${pager(res)}</div></section></div>${statusbar(label+(res?' · as of '+res.asOf:''))}</section>`;}
 async function loadList(){const m=client();if(!m)return;const ticket=++st.busy;try{const res=await m.collections({list:st.list,status:st.list==='overdue'?'all':st.status,sort:st.sort,page:st.page,pageSize:PAGE,...(st.search?{search:st.search}:{}),...(st.commodity&&st.list!=='overdue'?{commodity:st.commodity}:{})});if(ticket!==st.busy)return;st.res=res;}catch(err){if(!err.superseded)toast('Engine: '+err.message);}finally{if(ticket===st.busy)render();}}
 // ---- an account's collections ---------------------------------------------------------------------------------------
 function accountPage(id){const v=st.account;if(!v||v.accountId!==id)return empty(st.accountMsg||'Loading the account from the engine…');const a=acting(),f=v.flags||{},plan=v.budgetPlan;
  const acts=(v.actions||[]).map(x=>actButton(x,{accountId:v.accountId},a)).join('');
  const invs=table(['Invoice','Issued','Due','Amount due','Outstanding','Status','Disconnection','Last step','Actions'],v.invoices.map(i=>{const last=(i.dunning||[]).at(-1);return [e(i.invoiceId)+(i.budgetBilling?'<br><small>budget billing</small>':''),e(i.issuedAt),e(i.dueAt),money(i.amountDue)+(i.amountDue!==i.totalAmount?`<br><small>billed ${money(i.totalAmount)}</small>`:''),money(i.outstanding),e(i.status)+(i.heldBy?`<br><small class="ws-col-held">${e(i.heldBy)}</small>`:''),e(STATES[i.disconnection]||i.disconnection||''),last?`${e(last.label)}<br><small>${e(day(last.at))}</small>`:'',invoiceActs(i).length?`<div class="ws-col-acts">${invoiceActs(i).map(x=>actButton(x,{accountId:v.accountId,invoiceId:i.invoiceId},a)).join('')}</div>`:''];}),'No invoices yet in this run.');
  const arr=v.arrangements.length?group('Payment Arrangements',v.arrangements.map(x=>`<p class="gui-reason-description">${e(x.arrangementId)} · ${money(x.amount)} in ${x.instalments} instalments · ${e(x.state)}${x.endedAt?' '+e(day(x.endedAt)):''}${x.note?' · '+e(x.note):''}</p>${table(['Due','Amount','Paid'],x.schedule.map(s=>[e(s.dueAt),money(s.amount),day(s.paidAt)]),'')}`).join('')):'';
  const work=[...v.holds.map(h=>[`Dunning hold`,`${day(h.from)} to ${e(h.until)}${h.active?' (active)':''}`,e(h.note||'')]),...v.referrals.map(r=>[`Low-income referral ${caseLink(r.caseId)}`,`${day(r.referredAt)} · ${r.source==='you'?'you':'call centre'}`,e(r.outcome?`${r.outcome}${r.grant?' · grant '+money(r.grant):''}`:'agency decides by '+r.decideBy)])];
  return `<section class="fiori-shell gui-case-shell">${header('collections','Collections Account')}<nav class="gui-transaction-toolbar"><button type="button" data-col-back>‹ Back to list</button>${v.premiseId?`<button type="button" data-col-map="${e(v.premiseId)}">Show on map</button>`:''}</nav><div class="gui-case-scroll"><div class="gui-case-content">
   ${group('Contract Account',`<div class="gui-master-grid"><div>${field('Contract Acct',v.accountId)}${field('Customer',v.name)}${field('Address',v.address)}${field('Payment method',(v.paymentMethod||'').replaceAll('_',' '))}</div><div>${field('Balance',money(v.balance))}${field('Overdue',money(v.overdue))}${field('Outstanding',money(v.outstanding))}${field('Budget billing',plan?`${money(plan.instalment)} a month · ${plan.active?'active':'from '+day(plan.startsAt)}${plan.source==='master_data'?' (master data)':''}`:'No')}${field('Collections work',flagText(f)||'None')}</div></div>`)}
   ${group('Collections Actions',acts?`<div class="gui-inline-actions ws-col-acts">${acts}</div><p class="small-note">Recorded on the run date (${e(client()?.asOf||'')}) at 09:00; the engine replays the account's payments and dunning from then on.</p>`:'<p class="gui-processing-hint">No account action is open today.</p>')}
   ${group('Invoices',invs)}${arr}${work.length?group('Holds and Referrals',table(['Work','When','Outcome / reason'],work,'')):''}
   ${v.cases.length?group('Collections Cases',table(['Case','Category','Status','Created'],v.cases.map(c=>[caseLink(c.caseId),e(c.category),e(c.resolvedAt?`completed · ${c.outcome||''}`:'open'),day(c.createdAt)]),'')):''}
   ${group('Account Ledger',table(['Posted','Type','Amount','Reference'],[...v.ledger].reverse().map(l=>[day(l.at),e(String(l.type).replaceAll('_',' ')),money(l.amount),e(l.ref||'')]),'No postings yet.'))}
  </div></div>${statusbar('Collections account '+v.accountId+' · as of '+v.asOf)}</section>`;}
 async function loadAccount(id){const m=client();if(!m)return;const ticket=++st.busy;try{const v=await m.collectionsAccount(id);if(ticket!==st.busy)return;st.account=v;st.accountMsg='';}catch(err){if(!err.superseded){st.account=null;st.accountMsg=err.status===404?`Account ${id} is not in this town.`:err.message;}}finally{if(ticket===st.busy)render();}}
 // ---- outage follow-up -------------------------------------------------------------------------------------------
 function outagesPage(){const res=st.outages,o=st.of;if(!res)return empty('Loading the outage follow-up list from the engine…');
  const sum=table(['Interruption','Service','Start → end','Premises','Last gasps','Use lost','Missed reads','Open cases',''],(res.outages||[]).map(x=>[e(x.outageId),e(x.collectorOutage?'AMI collector':x.utility),`${e(day(x.start))} ${hm(x.start)} → ${hm(x.end)}${x.ongoing?' (ongoing)':''}`,x.premises,x.lastGasps,x.collectorOutage?'—':`${num(x.lostUse,1)} ${e(x.unit)}`,x.missedReads,x.openCases,`<button type="button" class="fiori-link" data-col-outage="${e(x.outageId)}">Rows</button>`]),'No service interruptions from the map yet.');
  const rows=(res.rows||[]).map(r=>[`${e(r.outageId)}<br><small>${e(r.collectorOutage?'AMI collector':r.utility)} · ${e(day(r.start))} ${hm(r.start)}</small>`,`${e(r.address)}<br><small>${e(r.premiseId)}</small>`,r.lastGasp?`🪫 ${hm(r.lastGaspAt)}`:'—',r.lostUse?`${num(r.lostUse,2)} ${e(r.unit)}`:'—',e(r.collectorId||''),r.missedReads.length?r.missedReads.map(x=>`${caseLink(x.caseId)} <small>${e(x.caseStatus||'no case')}${x.outcome?' · '+e(x.outcome):''}</small>`).join('<br>'):'—',e(r.followUp),`<button type="button" class="fiori-link" data-col-map="${e(r.premiseId)}">Map</button> <button type="button" class="fiori-link" data-col-watch="${e(r.premiseId)}" data-day="${e(r.day)}" data-seconds="${r.startSeconds}">Watch</button>`]);
  const tools=`<select data-col-ofilter="utility" aria-label="Service">${[['','All services'],['electric','Electric'],['water','Water'],['gas','Gas'],['ami','AMI collector']].map(([v,l])=>`<option value="${v}" ${o.utility===v?'selected':''}>${l}</option>`).join('')}</select><select data-col-ofilter="kind" aria-label="Rows">${KINDS.map(([v,l])=>`<option value="${v}" ${o.kind===v?'selected':''}>${l}</option>`).join('')}</select><select data-col-ofilter="status" aria-label="Follow-up">${[['all','All rows'],['open','Open missed-read cases']].map(([v,l])=>`<option value="${v}" ${o.status===v?'selected':''}>${l}</option>`).join('')}</select><input type="search" data-col-osearch value="${e(o.search)}" placeholder="Premise, address, case…" aria-label="Find in outage follow-up">${o.outage?`<button type="button" class="native-tool" data-col-outage="">All interruptions</button>`:''}<span class="spacer"></span><span>${res.total} row${res.total===1?'':'s'}</span>`;
  return `<section class="fiori-shell gui-case-shell">${header('outages')}<nav class="gui-transaction-toolbar"><button type="button" data-col-go="collections" data-id="disconnect">‹ Collections</button><button type="button" data-col-refresh>Update list</button></nav><div class="gui-case-scroll"><div class="gui-case-content"><p class="gui-reason-description">Each interruption from the map's operations days, per premise: the AMI last gasp of an electric meter that lost power, the use that never flowed, and the reads it cost, with their missed-read cases.</p>${group('Interruptions',sum)}<div class="clarification-table-toolbar">${tools}</div>${group(o.outage?'Premises · '+o.outage:'Premises',table(['Interruption','Premise','Last gasp','Use lost','Collector','Missed reads','Follow-up',''],rows,(res.outages||[]).length?'No rows match the filters.':'Outages feed this list: break a pole or a main on the map, or let a background incident happen.'))}${pager(res)}</div></div>${statusbar('Outage follow-up · as of '+res.asOf)}</section>`;}
 async function loadOutages(){const m=client();if(!m)return;const o=st.of,ticket=++st.busy;try{const res=await m.outageFollowup({status:o.status,page:o.page,pageSize:PAGE,...(o.utility?{utility:o.utility}:{}),...(o.kind?{kind:o.kind}:{}),...(o.search?{search:o.search}:{}),...(o.outage?{outageId:o.outage}:{})});if(ticket!==st.busy)return;st.outages=res;}catch(err){if(!err.superseded)toast('Engine: '+err.message);}finally{if(ticket===st.busy)render();}}
 // ---- a collector's missed reads as one problem -----------------------------------------------------------------
 function collectorPage(r){const g=st.group,rows=st.rows;if(!g||!rows)return empty(st.groupMsg||'Loading the collector from the engine…');const a=acting(),open=rows.filter(x=>!x.resolvedAt&&(x.actionableFrom||'')<=(client()?.asOf||''));
  return `<section class="fiori-shell gui-case-shell">${header('exceptions','Missed Reads on a Collector')}<nav class="gui-transaction-toolbar"><button type="button" data-col-back-cases>‹ Back to List</button><button type="button" data-col-estimate-all ${open.length&&!a?'':'disabled'}>${a?.act==='col:estimate-all'?'Recording…':`Estimate all open (${open.length})`}</button></nav><div class="gui-case-scroll"><div class="gui-case-content">
   ${group('AMI Collector',`<div class="gui-master-grid"><div>${field('Collector',g.collectorId)}${field('Mounted on',[g.mountedOn,g.mountId].filter(Boolean).join(' · ').replaceAll('_',' '))}${field('Day raised',g.day)}</div><div>${field('Cases',`${g.cases} (${g.open} open)`)}${field('Cause',g.cause?.label)}${field('Streets',(g.streets||[]).join(', '))}</div></div><p class="gui-reason-description">${e(g.label)}: one collector, one day. ${g.cause?.code==='collector_outage'?'The collector was down, so its meters could not report: estimate the reads or wait for the next read.':g.cause?.code==='power_outage'?'The meters lost power (AMI last gasps).':'The head-end got no reads from these meters; check the collector before sending crews to each premise.'}</p>`)}
   ${group('Cases',table(['Case','Address','Meter','Cause','Status'],rows.map(x=>[caseLink(x.caseId),e(x.address),e(x.meterId),e(x.cause?.label||x.label),e(x.resolvedAt?`completed · ${x.outcome||''}`:'open')]),'No cases.'))}
  </div></div>${statusbar(g.label+' · '+g.day)}</section>`;}
 async function loadCollector(r){const m=client();if(!m)return;const ticket=++st.busy;st.groupMsg='';try{const res=await m.collectorGroups({collector:r.record,status:'all',minCases:1,pageSize:200});let g=(res.groups||[]).find(x=>!r.day||x.day===r.day)||null;let rows=[];
   if(g){let page=1,total=1;while(rows.length<total){const q=await m.post('/process/queue',{status:'all',collector:g.collectorId,createdOn:g.day,page,pageSize:200},'collector-cases');total=q.total;rows=rows.concat(q.rows||[]);page++;if(!(q.rows||[]).length)break;}rows=rows.filter(x=>g.caseIds.includes(x.caseId));}
   if(ticket!==st.busy)return;st.group=g;st.rows=g?rows:null;if(!g)st.groupMsg=`No missed reads on collector ${r.record}${r.day?' on '+r.day:''} as of ${m.asOf||''}.`;}catch(err){if(!err.superseded){st.group=null;st.groupMsg=err.message;}}finally{if(ticket===st.busy)render();}}
 // Above the Meter Read Follow-Up list: the newest missed reads that share a collector and a day, one button each
 // (RPA often estimates comm fails overnight, so a group shows with its open count rather than only while open).
 function collectorStrip(){const m=client();if(!m)return '';const key=JSON.stringify(m.body({}));if(st.groupsKey!==key&&!st.loadingGroups){st.loadingGroups=true;m.collectorGroups({status:'all',minCases:2,pageSize:6}).then(res=>{st.groups=res;st.groupsKey=key;}).catch(()=>{st.groupsKey=key;}).finally(()=>{st.loadingGroups=false;render();});}
  const gs=st.groups?.groups||[];if(!gs.length)return '';return `<div class="ws-collector-strip" role="list" aria-label="Missed reads by AMI collector">${gs.map(g=>`<button type="button" role="listitem" data-col-go="collector" data-id="${e(g.collectorId)}" data-day="${e(g.day)}">📡 ${e(g.label)} · ${e(g.day)} · ${g.open} open · ${e(g.cause?.label||'')}${g.streets?.length?' · '+e(g.streets.slice(0,2).join(', ')):''} ›</button>`).join('')}${st.groups.total>gs.length?`<span>+${st.groups.total-gs.length} more groups</span>`:''}</div>`;}
 // ---- actions ----------------------------------------------------------------------------------------------------
 function dialog(form){return new Promise(resolve=>{let dlg=document.getElementById('ws-dialog');if(!dlg){dlg=document.createElement('dialog');dlg.id='ws-dialog';dlg.className='ws-dialog';document.body.append(dlg);}
  dlg.innerHTML=`<form class="clarification-action-form"><div class="dialog-head"><h2>${e(form.title)}</h2><button type="button" data-close aria-label="Close dialog">×</button></div>${form.text?`<p>${e(form.text)}</p>`:''}${form.fields.map(f=>`<label>${e(f.label)}${f.required?'':' (optional)'}${f.kind==='number'?`<input name="${f.name}" type="number" min="${f.min}" max="${f.max}" step="1" value="${e(f.value??'')}" ${f.required?'required':''}>`:`<textarea name="${f.name}" rows="3" maxlength="600" ${f.required?'required':''} placeholder="Why, or what was agreed"></textarea>`}</label>`).join('')}<div class="read-review-actions"><button type="submit">${e(form.submit)}</button><button type="button" data-close>Cancel</button></div><p class="small">Recorded as an engine action on the run date (${e(client()?.asOf||'')}).</p></form>`;
  let settled=false;const done=v=>{if(settled)return;settled=true;if(dlg.open)dlg.close();resolve(v);};dlg.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>done(null));
  dlg.querySelector('form').onsubmit=ev=>{ev.preventDefault();const out={};for(const f of form.fields){const el=dlg.querySelector(`[name="${f.name}"]`),v=el.value.trim();if(f.required&&!v){el.focus();return;}if(f.kind==='number'&&v!==''&&!(Number(v)>=f.min&&Number(v)<=f.max)){el.focus();return;}out[f.name]=v;}done(out);};dlg.oncancel=()=>done(null);dlg.showModal();(dlg.querySelector('input,textarea')||dlg.querySelector('[type=submit]')).focus();});}
 async function act(a,target){const m=client();if(!m||ui.acting)return;if(!m.canAct()){toast(`Actions are append-only: move the run date to ${m.lastActionDay()} or later.`);return;}const input=await dialog(actionForm(a,target));if(input==null)return;const {type,...extra}=actionBody(a,target,input);
  await recording(keyOf(a,target),async()=>{try{await m.act(type,null,null,extra);toast(`${ACTION_LABELS[a]||a}: recorded for ${isAccountAction(a)?'account '+target.accountId:target.invoiceId} on ${m.asOf}.`);await reload();}catch(err){if(!err.superseded)toast('Not recorded. '+refusal(err));}});}
 async function estimateAll(){const m=client(),open=(st.rows||[]).filter(x=>!x.resolvedAt&&(x.actionableFrom||'')<=(m?.asOf||''));if(!m||!open.length)return;
  await recording('col:estimate-all',async()=>{let done=0,refused=null;for(const x of open){try{await m.act('estimate',x.caseId);done++;}catch(err){refused=`${x.caseId}: ${refusal(err)}`;break;}}toast(refused?(done?`${done} estimated; not recorded: ${refused}`:`Not recorded. ${refused}`):`${done} missed reads on ${st.group.collectorId} estimated and released on ${m.asOf}.`);await loadCollector(ui.route);});}
 function reload(){const r=ui.route;if(r.tx==='collections')return loadList();if(r.tx==='account')return loadAccount(r.record);if(r.tx==='outages')return loadOutages();if(r.tx==='collector')return loadCollector(r);}
 function exportCsv(){const rows=st.res?.rows||[];if(!rows.length)return;const head=Object.keys(rows[0]).filter(k=>!['actions','flags','fees','commodities','invoiceIds','lastDunning'].includes(k)),csv=[head.join(','),...rows.map(r=>head.map(k=>JSON.stringify(r[k]??'')).join(','))].join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`collections-${st.list}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 // ---- mounting ---------------------------------------------------------------------------------------------------
 function page(r){if(r.tx==='collections'){st.list=r.list;return listPage();}if(r.tx==='account')return accountPage(r.record);if(r.tx==='outages')return outagesPage();return collectorPage(r);}
 function load(r){if(r.tx==='collections'){if(st.list!==r.list){st.list=r.list;st.page=1;st.res=null;}return loadList();}if(r.tx==='account')return loadAccount(r.record);if(r.tx==='outages')return loadOutages();if(r.tx==='collector'){st.group=null;st.rows=null;return loadCollector(r);}}
 let timer=null;const later=fn=>{clearTimeout(timer);timer=setTimeout(fn,300);};
 root?.addEventListener('click',ev=>{const t=ev.target;
  const b=t.closest('[data-col-act]');if(b&&!b.disabled){act(b.dataset.colAct,{accountId:b.dataset.account||null,invoiceId:b.dataset.invoice||null});return;}
  const g=t.closest('[data-col-go]');if(g){const k=g.dataset.colGo,id=g.dataset.id;if(k==='account')go({tx:'account',record:id});else if(k==='case')go({caseId:id});else if(k==='collector')go({tx:'collector',record:id,day:g.dataset.day||undefined});else if(k==='outages')go({tx:'outages'});else go({tx:'collections',list:id||st.list});return;}
  const p=t.closest('[data-col-page]');if(p&&!p.disabled){const n=Number(p.dataset.colPage);if(ui.route.tx==='outages'){st.of.page=n;loadOutages();}else{st.page=n;loadList();}return;}
  if(t.closest('[data-col-refresh]')){reload();return;}if(t.closest('[data-col-export]')){exportCsv();return;}
  if(t.closest('[data-col-clear]')){st.search='';st.commodity='';st.status='open';st.page=1;loadList();return;}
  if(t.closest('[data-col-back]')){go({tx:'collections',list:st.list});return;}if(t.closest('[data-col-back-cases]')){go({tx:'exceptions'});return;}
  const mp=t.closest('[data-col-map]');if(mp){onShowPremise(mp.dataset.colMap);return;}
  const w=t.closest('[data-col-watch]');if(w){onWatch({premiseId:w.dataset.colWatch,day:w.dataset.day,seconds:Number(w.dataset.seconds)||0});return;}
  const o=t.closest('[data-col-outage]');if(o){st.of.outage=o.dataset.colOutage||'';st.of.page=1;loadOutages();return;}
  if(t.closest('[data-col-estimate-all]')&&!ui.acting)estimateAll();});
 root?.addEventListener('change',ev=>{const t=ev.target;
  if(t.matches('[data-col-list]')){if(t.value==='outages')go({tx:'outages'});else go({tx:'collections',list:t.value});}
  else if(t.matches('[data-col-filter]')){st[t.dataset.colFilter]=t.value;st.page=1;loadList();}
  else if(t.matches('[data-col-ofilter]')){st.of[t.dataset.colOfilter]=t.value;st.of.page=1;loadOutages();}
  else if(t.matches('[data-col-more]')&&t.value){const a=t.value;t.value='';act(a,{accountId:t.dataset.account||null,invoiceId:t.dataset.invoice||null});}
  else if(t.id==='ws-period'){st.period=t.value;reopen();}});
 root?.addEventListener('input',ev=>{const t=ev.target;if(t.matches('[data-col-search]')){st.search=t.value;st.page=1;later(loadList);}else if(t.matches('[data-col-osearch]')){st.of.search=t.value;st.of.page=1;later(loadOutages);}});
 // Run statistics: the period selector, and the day the selected period starts.
 const periodSelect=()=>`<label class="ws-period">Period <select id="ws-period">${PERIODS.map(([v,l])=>`<option value="${v}" ${st.period===v?'selected':''}>${l}</option>`).join('')}</select></label>`;
 const since=()=>{const m=client();return periodStart(st.period,m?.asOf||null,m?.firstActionDay?.()||null);};
 return {page,load,nav,collectorStrip,caseExtras,periodSelect,since,periodBody,collectionsGroup,state:st};
}
